"""
Product Management Question Builder (pm_4 to pm_100)
Provides 97 distinct, high-quality interview questions for Product Management.
"""

def get_pm_questions():
    questions_raw = [
        # Strategy & Market Opportunity
        (4, "How do you evaluate whether a product has achieved Product-Market Fit (PMF)?", "Medium",
         ["product market fit", "PMF", "retention curve", "Sean Ellis test", "organic growth", "churn", "NPS"],
         "Combine quantitative retention curves (flattening cohorts), Sean Ellis 40% 'very disappointed' survey metric, and organic word-of-mouth referral rates.",
         "Product-Market Fit (PMF) means being in a good market with a product that can satisfy that market. I evaluate PMF using three primary indicators: 1) Cohort Retention Curves: If retention curves flatten parallel to the x-axis after 30/60/90 days rather than trending toward zero, the product provides sustainable baseline value; 2) The Sean Ellis Test (40% Rule): Surveying active users with 'How would you feel if you could no longer use this product?'; if >= 40% answer 'very disappointed', strong PMF is present; 3) Organic Growth Engine: High Net Promoter Score (NPS) and significant organic word-of-mouth adoption without paid acquisition subsidies."),

        (5, "How do you calculate Total Addressable Market (TAM), SAM, and SOM for a new product?", "Medium",
         ["TAM", "SAM", "SOM", "market sizing", "top-down", "bottom-up", "ARPU", "serviceable market"],
         "Distinguish Top-Down (industry reports) from Bottom-Up (units * average revenue per user). Explain TAM (total demand), SAM (reachable segment), SOM (realistic target).",
         "I use a Bottom-Up approach because it grounds market sizing in operational reality rather than broad industry reports. 1) Total Addressable Market (TAM): The total worldwide demand if 100% of potential customers bought the product (TAM = Total Potential Accounts * Average Annual Contract Value); 2) Serviceable Addressable Market (SAM): The portion of TAM that fits our specific geography, technical platform, or customer segment; 3) Serviceable Obtainable Market (SOM): The realistic market share we can capture within 2-3 years given our current sales capacity, marketing budget, and competitive dynamics."),

        (6, "What constitutes a sustainable Competitive Moat according to Warren Buffett and Hamilton Helmer (7 Powers)?", "Hard",
         ["moat", "7 powers", "network effects", "switching costs", "scale economies", "counter-positioning", "defensibility"],
         "Discuss Helmer's 7 Powers: Scale Economies, Network Effects, Counter-Positioning, Switching Costs, Branding, Cornered Resource, Process Power.",
         "A competitive moat provides durable economic defensibility against rival entry. Based on Hamilton Helmer's 7 Powers: 1) Network Effects: Each new user increases product utility for all other users (e.g., Slack, Airbnb); 2) Switching Costs: High migration friction in data, workflows, or employee retraining (e.g., Salesforce, SAP); 3) Scale Economies: Lower per-unit cost as production volume expands (e.g., AWS, Netflix content amortisation); 4) Counter-Positioning: Adopting a business model that incumbents cannot copy without cannibalizing existing revenues; 5) Cornered Resource: Exclusive access to proprietary IP, patents, or talent; 6) Branding: Emotional trust premium; and 7) Process Power: Embedded operational excellence."),

        (7, "How would you price a new B2B SaaS software product?", "Hard",
         ["pricing strategy", "value-based pricing", "cost-plus", "competitor-based", "pricing tiers", "willingness to pay", "van Westendorp"],
         "Reject cost-plus pricing. Explain Value-Based Pricing, identifying value metrics (per user, per compute, per transaction), and Van Westendorp Price Sensitivity analysis.",
         "I avoid cost-plus pricing and implement Value-Based Pricing: 1) Identify the Value Metric: Determine the core unit of customer value consumption that scales naturally with their business growth (e.g., active seats for collaboration software, processed transaction volume for Stripe, API requests for Twilio); 2) Quantify Economic Value Delivered: Calculate the revenue lift or cost savings the tool provides to target customer personas; 3) Van Westendorp Price Sensitivity Meter: Conduct customer surveys across price thresholds ('too cheap', 'bargain', 'expensive', 'too expensive'); 4) Package into 3 Tiers (Starter for self-serve, Pro for growing teams, Enterprise for compliance/SSO)."),

        (8, "Explain the Kano Model and how customer expectations shift over time.", "Easy",
         ["Kano model", "must-have", "performance", "delighters", "feature degradation", "customer satisfaction"],
         "Categorize into Must-Haves (Basic), Performance (Linear), and Delighters (Excitement). Explain how delighters degrade into must-haves over time.",
         "The Kano Model maps feature investment against customer satisfaction: 1) Must-Haves (Basic Needs): Features taken for granted (e.g., password reset, encryption); their presence does not delight users, but their absence causes severe dissatisfaction; 2) Performance Features: Satisfaction scales linearly with execution (e.g., faster page load speed, longer battery life, search relevance); 3) Delighters (Excitement): Unexpected features that generate outsized delight (e.g., Google Docs real-time co-typing in 2006). Crucially, delighters inevitably decay into baseline must-haves over time as competitors adopt them (e.g., mobile dark mode)."),

        (9, "How do you define and choose a North Star Metric for a digital product?", "Medium",
         ["north star metric", "KPI", "customer value", "business value", "leading indicator", "DAU", "Aha moment"],
         "A North Star Metric must measure customer value delivery, serve as a leading indicator of revenue, and be actionable by cross-functional teams.",
         "A North Star Metric is the single key metric that best captures the core value a product delivers to its customers while driving sustainable long-term business revenue. A good North Star must meet three criteria: 1) It measures customer value realized (e.g., Spotify's metric is 'Time Spent Listening', Airbnb is 'Nights Booked', Slack is 'Messages Sent in Teams'); 2) It is a Leading Indicator of revenue and retention rather than a lagging financial indicator like MRR; 3) It is understandable and directly influenceable by engineering, design, and marketing teams."),

        (10, "What are Guardrail / Counter-Metrics, and why are they critical in A/B testing?", "Easy",
         ["guardrail metrics", "counter-metrics", "A/B testing", "trade-offs", "cannibalization", "latency", "churn"],
         "Explain that optimizing a single primary metric often creates unintended negative side effects (e.g. clickbait boosting CTR but destroying retention).",
         "Guardrail (or Counter) Metrics protect the broader ecosystem from the unintended negative side effects of optimizing a single primary metric. For example, if a team runs an experiment to increase checkout conversion, aggressive modal popups might lift short-term conversion by 2% while causing a 15% increase in user support tickets, a 10% rise in cart abandonment, or increased credit card chargebacks. Critical guardrail categories include: technical performance (p95 page load latency, crash rates), trust metrics (unsubscribe rates, spam reports), and business health (gross margins, long-term churn). An experiment cannot be shipped if guardrail thresholds are violated."),

        (11, "How do you calculate and optimize Customer Lifetime Value (LTV) to Customer Acquisition Cost (CAC)?", "Medium",
         ["LTV", "CAC", "unit economics", "payback period", "churn rate", "ARPU", "SaaS metrics"],
         "Formulas: LTV = (ARPU * Gross Margin) / Churn Rate. CAC = Total Sales & Marketing Spend / New Customers Acquired. Benchmark ratio is 3:1.",
         "The LTV:CAC ratio measures the unit economic health of a business. LTV is calculated as (Average Revenue Per User * Gross Margin %) / Churn Rate. CAC is Total Sales and Marketing Costs divided by Total New Customers Acquired over a given period. A healthy SaaS benchmark is 3:1 (generating $3 of lifetime value for every $1 spent on acquisition). If the ratio is below 1:1, the business is burning cash unsustainably. If the ratio exceeds 5:1, the company is underinvesting in marketing and leaving market share on the table. Another vital metric is CAC Payback Period (months to recover acquisition costs), which should ideally remain under 12 months."),

        (12, "What is the Jobs-to-be-Done (JTBD) framework and how does it prevent feature creep?", "Easy",
         ["jobs to be done", "JTBD", "Clayton Christensen", "customer problem", "milkshake study", "outcome driven"],
         "Cite Clayton Christensen's milkshake study: people don't buy products, they 'hire' them to make progress in specific circumstances.",
         "The Jobs-to-be-Done (JTBD) framework posits that customers do not buy products or features; they 'hire' products to make progress in a specific life situation. The classic example is Clayton Christensen's McDonald's milkshake study: commuters hired milkshakes in the morning not because they loved dessert, but because they needed a clean, thick, one-handed food that would keep them engaged during a boring commute and stave off hunger until lunch. JTBD frames features as solutions to underlying struggles, formulated as: 'When I [situation], I want to [motivation], so that I can [desired outcome].' It stops feature creep by forcing teams to validate the underlying job before building solutions."),

        (13, "How do you run effective User Discovery Interviews without introducing Confirmation Bias?", "Medium",
         ["user discovery", "interview", "confirmation bias", "The Mom Test", "open-ended questions", "qualitative research"],
         "Reference Rob Fitzpatrick's 'The Mom Test': talk about the customer's actual past behavior and life, never ask about hypothetical future intentions.",
         "To conduct unbiased user discovery, I follow Rob Fitzpatrick's 'The Mom Test' principles: 1) Talk about their life and past behavior, not your idea or prototype: ask 'When was the last time you encountered this problem? Walk me through what you did step-by-step', rather than 'Would you buy a tool that does X?'; 2) Ask open-ended questions and listen 80% of the time, resisting the urge to pitch features; 3) Dig into their current workarounds: if they haven't actively spent time or money trying to solve the problem with manual spreadsheets or duct-taped tools, the pain point is not acute enough to warrant building a product."),

        (14, "How do you handle a disagreement between Product, Engineering, and Design on a feature direction?", "Medium",
         ["stakeholder management", "consensus", "disagreement", "alignment", "experimentation", "design engineering triad"],
         "Ground decisions in user data and company goals rather than opinions. Frame disagreements as hypotheses to test via spikes or user tests.",
         "Disagreements across the Product-Design-Engineering triad are healthy and reflect differing perspectives on feasibility, usability, and business value. To resolve conflict: 1) Re-anchor on the Shared Goal: Revisit the problem statement and the specific OKR or customer outcome we are solving; 2) Separate Facts from Hypotheses: Document what is backed by data versus what is an assumption; 3) Low-Cost De-risking: Instead of endless theoretical debates in meetings, run a quick design prototype user test with 5 customers, or commission an engineering spike to validate technical feasibility; 4) Commit and Disagree: If time is critical, the PM makes the call, documents the rationale and risk mitigation, and ensures total team commitment."),

        (15, "What is the difference between an MVP (Minimum Viable Product) and an MLP (Minimum Lovable Product)?", "Easy",
         ["MVP", "MLP", "minimum viable product", "minimum lovable product", "user experience", "validation"],
         "MVP focuses on testing business hypotheses with the minimum possible effort; MLP ensures that what is shipped is delightful enough to build loyalty.",
         "A Minimum Viable Product (MVP), popularized by Eric Ries, is the version of a new product that allows a team to collect the maximum amount of validated learning about customers with the least effort. However, in saturated competitive markets, a purely functional or clunky MVP can alienate users. A Minimum Lovable Product (MLP) builds upon the core viable foundation by ensuring the limited initial scope is executed with exceptional craft, intuitive UX, and delightful design, so that early adopters do not merely tolerate the tool, but actively love it and advocate for it."),

        (16, "How do you manage Scope Creep during sprint execution without demoralizing the team?", "Easy",
         ["scope creep", "sprint planning", "backlog", "trade-offs", "agile", "prioritization", "buffer"],
         "Emphasize the Iron Triangle (Scope, Time, Resources). When new requirements emerge, ask: 'What existing item should we deprioritize to fit this in?'",
         "Scope creep occurs when new requirements, edge cases, or stakeholder requests infiltrate an active sprint or release milestone. To handle it constructively: 1) Enforce the Iron Triangle (Scope, Time, Resources): Make trade-offs transparent—if scope expands and the release deadline is fixed, we must either deprioritize an existing backlog item or accept lower fidelity; 2) The 'Parking Lot' / Icebox: Acknowledge the value of new ideas, record them in the backlog with clear acceptance criteria, and review them during the next sprint grooming rather than derailing active work; 3) Protect engineering focus while remaining flexible for genuine business emergencies."),

        (17, "What is the difference between Scrum and Kanban, and when would you choose one over the other?", "Easy",
         ["scrum", "kanban", "agile", "sprint", "WIP limits", "continuous flow", "velocity"],
         "Scrum is time-boxed (fixed 2-week sprints, sprint backlog, roles); Kanban is continuous flow with Work-In-Progress (WIP) limits.",
         "Scrum organizes work into fixed-length time-boxed iterations (typically 1- to 2-week sprints) with defined ceremonies (Sprint Planning, Daily Standup, Sprint Review, Retrospective) and prescribed roles (Product Owner, Scrum Master, Developers). It excels for feature delivery teams building planned roadmap initiatives where velocity and sprint forecasting matter. Kanban is a continuous flow model without fixed sprints: tasks move continuously across stages visualized on a board, governed by strict Work-In-Progress (WIP) limits to prevent bottlenecks. Kanban is superior for operational teams, maintenance/DevOps, or mature products managing unpredictable bug fixes and support tickets."),

        (18, "How do you write a clear, effective Product Requirements Document (PRD)?", "Medium",
         ["PRD", "product requirements", "problem statement", "user stories", "acceptance criteria", "non-functional requirements", "metrics"],
         "Structure: Problem Statement & Why -> Target Persona -> Success Metrics & Guardrails -> User Journeys & Requirements -> Out of Scope -> Risks.",
         "An effective PRD aligns cross-functional teams around what to build and why, leaving 'how' to engineering and design. My PRD structure contains: 1) Executive Summary & Problem Statement: The customer pain point grounded in data; 2) Target Personas & Use Cases; 3) Success Metrics: The North Star, secondary adoption metrics, and guardrail metrics; 4) User Stories & Detailed Acceptance Criteria: Structured as 'Given / When / Then' scenarios; 5) Non-Functional Requirements: Performance latency, compliance, security; 6) Explicit Out-of-Scope boundaries to prevent scope creep; and 7) Open Questions & Release Rollout Plan."),

        (19, "How do you sunset (deprecate) a legacy feature that a small group of vocal users still uses?", "Hard",
         ["sunsetting", "feature deprecation", "legacy feature", "customer communication", "migration", "technical debt"],
         "Show empathy, transparency, and data. Provide alternative workflows, advance migration timelines, and automated migration scripts.",
         "Deprecating features requires balancing engineering maintenance costs with customer goodwill: 1) Data Audit: Analyze telemetry to quantify exactly who uses the feature and for what workflows; 2) Build Alternatives or Migration Paths: Ensure equivalent capabilities exist in the modern platform, providing self-serve export tools or automated migration scripts; 3) Proactive Transparent Communication: Announce the deprecation schedule 6-12 months in advance via in-app banners, email, and direct reach-outs to key accounts; 4) Phased Decommissioning: First stop allowing new users to enable the feature, then restrict editing, and finally decommission after the sunset date, celebrating the team's reduction of tech debt."),

        (20, "What is a Flywheel effect in product growth, and how do you identify its compounding loops?", "Hard",
         ["flywheel", "growth loops", "compounding", "network effects", "user acquisition", "Amazon flywheel"],
         "Contrast linear funnels (acquire, convert, churn) with compounding loops where output of one cycle feeds directly as input for the next cycle.",
         "Linear funnels (Acquisition -> Activation -> Retention -> Revenue) are extractive: you invest capital at the top, and users leak out at each stage. A Product Flywheel (or Growth Loop) is a self-reinforcing closed-loop system where the output of one user's action becomes the input that drives the acquisition, engagement, or retention of subsequent users. For example, Amazon's flywheel: Lower prices attract more customers -> attracts more third-party sellers -> generates economies of scale -> lowers cost structure, enabling even lower prices. Similarly, in Figma, a designer creates an asset and invites stakeholders to review -> stakeholders sign up to comment -> stakeholders become creators, driving organic exponential growth."),
    ]

    # Additional 77 questions to reach 97 new questions (pm_4 to pm_100)
    topics_21_to_100 = [
        (21, "How do you design an effective onboarding flow to accelerate Time-to-Value (TTV)?", "Easy",
         ["onboarding", "time-to-value", "TTV", "activation", "aha moment", "friction", "product-led growth"],
         "Identify the 'Aha!' moment and eliminate every unnecessary form field, step, and cognitive friction between signup and value realization.",
         "Time-to-Value (TTV) is the duration between when a user first signs up and when they experience the product's core value (the 'Aha! moment'). To optimize onboarding: 1) Identify the Aha! moment using behavioral cohort analytics (e.g., Slack discovered teams sending 2,000 messages retained at 93%); 2) Eliminate friction: remove unnecessary upfront setup steps, email verifications, and credit card requirements; 3) Provide empty-state templates and interactive product tours (e.g., Notion pre-populating templates); and 4) Implement progressive disclosure, introducing advanced features only after basic activation is achieved."),

        (22, "What is Product-Led Growth (PLG) and how does it contrast with Sales-Led Growth?", "Medium",
         ["PLG", "product led growth", "freemium", "self-serve", "sales-led", "viral expansion", "bottom-up"],
         "PLG uses the product itself as the primary vehicle to acquire, activate, and retain users (freemium/self-serve), expanding bottom-up into enterprise.",
         "Product-Led Growth (PLG) is a go-to-market strategy that relies on the product experience itself as the primary driver of customer acquisition, retention, and expansion. Users experience value immediately through self-serve freemium models or free trials before paying (e.g., Zoom, Slack, Canva). Growth occurs bottom-up: individual end-users adopt the tool for their daily workflow, form viral peer loops, and eventually force corporate IT to negotiate an enterprise contract. In Sales-Led Growth (SLG), customer acquisition relies on enterprise sales reps, RFPs, demo calls, and top-down executive purchasing decisions before any end-user ever touches the software."),

        (23, "How do you conduct a competitive analysis without falling into the 'Feature Parity Trap'?", "Medium",
         ["competitive analysis", "feature parity", "differentiation", "value proposition", "strategy", "competitor"],
         "Focus on competitors' strategic trade-offs and underserved customer segments rather than building a checklist of their features.",
         "The Feature Parity Trap occurs when a product team treats a competitor's feature matrix as a roadmap checklist, resulting in bloated, undifferentiated software that is perpetually one step behind. To perform strategic competitive analysis: 1) Analyze Competitor Trade-offs: Identify what the competitor intentionally does poorly or ignores to excel in their primary niche; 2) Map Customer Segments: Identify underserved or over-served customer cohorts; 3) Evaluate Strengths and Defensibility: Assess their core moats (distribution, data, switching costs); and 4) Focus on Differentiated Value: Double down on unique value propositions where your product can be 10x better rather than 10% cheaper."),

        (24, "What is the difference between Leading and Lagging indicators in product analytics?", "Easy",
         ["leading indicator", "lagging indicator", "metrics", "churn", "retention", "revenue", "early warning"],
         "Lagging indicators measure past results (revenue, quarterly churn); Leading indicators predict future performance (weekly active usage, onboarding drop-off).",
         "1) Lagging Indicators reflect the historical outcome of past actions, measuring final business results after the fact (e.g., Monthly Recurring Revenue, quarterly customer churn rate, customer renewal rates). By the time a lagging metric drops, it is too late to prevent the damage; 2) Leading Indicators are predictive, real-time behavioral signals that correlate strongly with future lagging outcomes (e.g., daily active logins, feature adoption rates, frequency of support tickets, or search query volume). Product teams focus their day-to-day optimizations on leading indicators because they provide actionable early warnings that allow teams to intervene before revenue or retention suffers."),

        (25, "How do you prioritize bugs versus technical debt versus new feature development?", "Medium",
         ["bug prioritization", "technical debt", "feature development", "capacity allocation", "sprint planning", "triage"],
         "Establish a balanced capacity allocation budget (e.g., 60% new features, 20% technical debt & architecture, 20% bugs & customer delight).",
         "Balancing competing demands requires transparent allocation frameworks: 1) Capacity Allocation: Formally agree with engineering and leadership on a recurring sprint allocation ratio—such as 60% new strategic features, 20% technical debt/refactoring, and 20% bug fixes/unplanned maintenance; 2) Severity-Based Bug Triage: Classify bugs into tiers (P0 critical blockers resolved immediately within hours; P1 high priority fixed in current sprint; P2/P3 prioritized against new features based on frequency and business impact); 3) Quantify Tech Debt: Frame technical debt in terms of business cost (e.g., reduced velocity or increased outage frequency)."),

        (26, "How do you evaluate whether to build a feature In-House versus Buy a third-party SaaS solution?", "Medium",
         ["build vs buy", "core competency", "time to market", "vendor lock-in", "maintenance cost", "total cost of ownership"],
         "Assess: Is this capability our core competitive advantage? If yes, BUILD. If it is commodity infrastructure (auth, billing, search), BUY.",
         "The Build vs Buy framework evaluates: 1) Core Competency: Is this capability a proprietary competitive differentiator that defines our value proposition? If yes (e.g., Netflix recommendation algorithms), BUILD. If it is commodity plumbing (e.g., email delivery via SendGrid, user auth via Auth0, billing via Stripe), BUY; 2) Total Cost of Ownership (TCO): Factor in not just upfront engineering build hours, but ongoing maintenance, security patching, SLA monitoring, and developer context switching; 3) Time to Market: Buying delivers immediate value, accelerating product launch by months."),

        (27, "Explain the difference between Virality (K-Factor) and Network Effects.", "Medium",
         ["virality", "K-factor", "network effects", "organic growth", "utility", "viral coefficient"],
         "Virality describes acquisition speed (users bringing other users); Network effects describe retention and utility (product becomes more valuable as users join).",
         "While often confused, they describe fundamentally different mechanics: 1) Virality (Viral Coefficient / K-Factor) is an acquisition mechanism where an existing user invites or brings new users into the product through their usage (e.g., Zoom sending a meeting link, PayPal referral bonuses, or Hotmail email footers). K = invites sent per user * conversion rate; if K > 1, growth is exponential. However, viral products can churn users just as quickly; 2) Network Effects describe product utility: every additional user increases the intrinsic value and defensibility of the service for all existing users (e.g., Craigslist, eBay, telephone networks)."),

        (28, "What are the common pitfalls of relying solely on Net Promoter Score (NPS)?", "Easy",
         ["NPS", "net promoter score", "survey bias", "actionability", "promoters", "detractors", "customer satisfaction"],
         "NPS is a lagging, non-actionable aggregate that suffers from cultural response bias, sampling bias, and arbitrary classification thresholds.",
         "While Net Promoter Score ('How likely are you to recommend us to a friend or colleague? 0-10') is widely tracked by executives, relying on it blindly presents severe pitfalls: 1) Lack of Actionability: An aggregate score of 42 does not reveal why users are unhappy or what specific features need fixing; 2) Cultural & Response Bias: American respondents frequently award 9s and 10s, whereas European and Asian respondents rarely give 10s due to cultural calibration; 3) Sampling Bias: Happy active users are far more likely to complete the survey than churned or frustrated users; 4) Arbitrary Thresholds: Treating a 6 as a 'Detractor' and an 8 as 'Passive' masks subtle sentiment shifts."),

        (29, "How do you calculate Churn Rate and differentiate Customer Churn from Revenue Churn?", "Medium",
         ["churn rate", "customer churn", "revenue churn", "net negative churn", "expansion revenue", "SaaS metrics"],
         "Customer Churn = % of logos lost. Revenue Churn = % of ARR lost. Net Negative Churn occurs when expansion revenue from retained users exceeds churn.",
         "In recurring revenue businesses: 1) Logo (Customer) Churn Rate: The percentage of active subscribers who cancel their accounts within a given period (Lost Customers / Starting Customers). A healthy B2B SaaS annual logo churn is 5%-8%; 2) Revenue (MRR/ARR) Churn Rate: The percentage of recurring revenue lost to cancellations and downgrades. Crucially, Net Revenue Churn can be NEGATIVE (Net Negative Churn): when expansion revenue (upsells, seat additions, feature tier upgrades) from retained customers exceeds the revenue lost from churned customers. A company with negative net churn grows revenue even if it acquires zero new customers."),

        (30, "What is the RICE scoring model and how do you calculate Confidence?", "Easy",
         ["RICE", "prioritization", "reach", "impact", "confidence", "effort", "product management"],
         "Formula: (Reach * Impact * Confidence) / Effort. Confidence discounts optimistic speculation using quantitative evidence.",
         "RICE is a quantitative prioritization framework: 1) Reach: How many customers will this feature impact within a given timeframe (e.g., 2,000 users/month); 2) Impact: Quantitative business value (0.25 minimal, 0.5 low, 1 medium, 2 high, 3 massive); 3) Confidence: A percentage discounting subjective optimism based on evidence rigor (100% high confidence backed by customer interviews and data; 80% medium backed by surveys; 50% low based on intuition); 4) Effort: Total engineering sprints required. RICE Score = (Reach * Impact * Confidence) / Effort. Ranking by RICE score reveals high-leverage quick wins."),

        (31, "How do you design a Pricing Experiment without alienating existing customers?", "Hard",
         ["pricing experiment", "price elasticity", "grandfathering", "cohort testing", "willingness to pay", "A/B testing pricing"],
         "Never A/B test different prices to concurrent users (violates fairness). Test price elasticity on new acquisition cohorts and grandfather existing users.",
         "A/B testing two different prices simultaneously to identical active customers is disastrous: users discover the price disparity on Reddit/Twitter, triggering PR backlash and chargebacks. Safe pricing experimentation methods: 1) Grandfather Existing Users: Guarantee that existing subscribers retain their legacy pricing, testing price increases exclusively on new signups; 2) Clean Cohort or Geographic Segmentation: Test new price points across distinct marketing landing pages, new packaging tiers, or separate international geographic markets; 3) Unbundling or Packaging Experiments: Test adding new premium feature modules at a separate price point rather than altering base subscription rates."),

        (32, "What is Cohort Analysis and how do you interpret a Retention Heatmap?", "Medium",
         ["cohort analysis", "retention heatmap", "user retention", "churn", "lifecycle", "behavioral cohorts"],
         "Track groups of users who signed up in the same time period across subsequent weeks/months. Flattening curves reveal PMF; drop-offs pinpoint churn.",
         "Cohort Analysis tracks groups of users who share a common starting characteristic—typically their signup or acquisition week/month—over subsequent time intervals (Days 1, 7, 14, 30, 90). In a Retention Heatmap: 1) Rows represent acquisition cohorts (e.g., January 2026 cohort, February 2026 cohort); 2) Columns represent time elapsed since signup; 3) Color shading highlights percentage retention. Reading horizontally reveals how quickly a specific cohort churns and whether retention stabilizes. Reading vertically compares retention across successive cohorts at the same lifecycle stage, evaluating whether recent product onboarding improvements successfully increased retention."),

        (33, "How do you define a Target User Persona versus an Anti-Persona?", "Easy",
         ["persona", "anti-persona", "target audience", "customer segment", "ideal customer profile", "ICP"],
         "A Persona defines who you build for (goals, pain points). An Anti-Persona defines who you intentionally DO NOT build for, preventing distraction.",
         "An Ideal Customer Persona (ICP) represents a synthesized archetype of the primary target user whose acute problem your product solves best, outlining their daily responsibilities, technical fluency, core JTBD motivations, and key workflows. An Anti-Persona represents the user segment you deliberately choose NOT to serve. For example, a developer-first CLI tool's anti-persona might be non-technical enterprise executives who demand drag-and-drop web GUIs and lengthy RFP cycles. Documenting anti-personas gives the product and sales teams permission to say 'No' to distracting feature requests that would pull the product away from its core focus."),

        (34, "What is the difference between Feature Toggles (Flags) and Canary Deployments from a PM perspective?", "Easy",
         ["feature flags", "canary deployment", "beta testing", "risk mitigation", "continuous delivery", "rollout"],
         "Canary is an infrastructure-level traffic split; Feature Flags are application-level switches enabling targeted user cohort activation.",
         "From a product management standpoint: 1) Canary Deployments are an infrastructure-level DevOps mechanism that routes a tiny random percentage of live production traffic (e.g., 2% of anonymous HTTP requests) to new backend server code to verify CPU utilization, latency, and error budgets before full rollout; 2) Feature Flags (Feature Toggles) are application-level switches embedded in code that decouple code deployment from feature release. They allow the PM to enable a feature dynamically for specific targeted user cohorts (e.g., 10 beta customers, employees only, or users in Germany) without re-deploying code, and permit instant kill-switch deactivation if issues arise."),

        (35, "How do you run a Post-Mortem Retrospective after a failed product launch?", "Medium",
         ["post-mortem", "retrospective", "blameless", "root cause", "5 whys", "continuous learning", "incident review"],
         "Enforce a blameless culture, apply the 5 Whys to uncover systemic root causes, document actionable takeaways, and celebrate learnings.",
         "A post-mortem after an unsuccessful feature launch should be blameless and focused on institutional learning: 1) Timeline & Data Review: Document the chronological sequence of events, customer telemetry, adoption funnels, and unpredicted roadblocks; 2) The 5 Whys Root Cause Analysis: Repeatedly drill into why assumptions failed (e.g., 'Why was adoption 2%?' -> 'Users did not discover the button' -> 'Why?' -> 'It was hidden behind secondary settings'); 3) Re-evaluate Core Hypotheses: Was it an execution failure (bad UX/bugs) or a strategic market failure (users do not care about this problem?); 4) Assign concrete systemic action items."),

        (36, "What is a Customer Journey Map and how do you identify friction points?", "Easy",
         ["customer journey map", "touchpoints", "friction points", "pain points", "user experience", "empathy map"],
         "Map every stage (Awareness -> Consideration -> Onboarding -> Daily Use -> Renewal) detailing user actions, emotions, and friction.",
         "A Customer Journey Map visualizes the complete end-to-end experience a user has with a product across multiple touchpoints over time. It is structured into sequential stages: Discovery/Awareness -> Evaluation -> Onboarding -> Daily Core Workflow -> Advocacy/Renewal. For each stage, the map documents: 1) User Actions (what they are physically doing); 2) Touchpoints (channels: mobile app, desktop, support email); 3) Thoughts and Emotional State (confidence vs confusion); and 4) Friction Points and Blockers (confusing terminology, redundant inputs, delayed email links). Identifying clusters of negative emotions highlights prime opportunities for UX optimization."),

        (37, "How do you manage an executive stakeholder who demands their pet feature be built immediately?", "Medium",
         ["stakeholder management", "executive buy-in", "saying no", "trade-offs", "prioritization", "roadmap alignment"],
         "Acknowledge the idea, understand their underlying business motive, frame the request against active OKRs, and present transparent trade-offs.",
         "Saying 'No' to senior leadership requires diplomacy, empathy, and data: 1) Listen to Understand the Underlying Why: Uncover the business goal behind their request (e.g., 'Is this driven by a specific enterprise prospect at risk, or strategic vision?'); 2) Validate the Problem, Not the Prescribed Solution; 3) Frame the Decision in Terms of Trade-offs: Transparently show the active roadmap and ask: 'To build this pet feature this quarter, we would have to pull resources from the Stripe international checkout project, delaying our $2M revenue expansion goal. Should we make that trade?'; 4) Offer an alternative: commission a light design spike or customer survey to gather objective data first."),

        (38, "Explain the difference between Qualitative and Quantitative user research.", "Easy",
         ["qualitative research", "quantitative research", "user testing", "analytics", "sample size", "user empathy"],
         "Quantitative tells you WHAT is happening (analytics, A/B tests, conversion rates); Qualitative tells you WHY it is happening (interviews, usability tests).",
         "Both research paradigms are essential and mutually reinforcing: 1) Quantitative Research gathers numerical, statistically significant data from large sample sizes (e.g., Google Analytics funnels, SQL queries, A/B test lift, survey rating scales). It objectively tells you WHAT users are doing, where drop-offs occur, and how widespread an issue is; 2) Qualitative Research gathers observational, descriptive insights from smaller cohort sizes (e.g., 1-on-1 customer interviews, diary studies, usability observation sessions). It tells you WHY users behave that way—their emotional frustrations, mental models, and unspoken workarounds. Good PMs use quantitative data to spot problems and qualitative data to understand causes."),

        (39, "What is the Opportunity Solution Tree framework developed by Teresa Torres?", "Medium",
         ["opportunity solution tree", "Teresa Torres", "continuous discovery", "outcomes", "opportunities", "solutions", "experiments"],
         "Structure: Desired Outcome (top) -> Customer Opportunities/Pain Points -> Potential Solutions -> Specific Assumption Tests (bottom).",
         "The Opportunity Solution Tree is a visual framework created by Teresa Torres that guides continuous product discovery: 1) Desired Outcome (Root): The measurable business metric or OKR the team is accountable for (e.g., increase 30-day retention by 5%); 2) Opportunities (Branches): Customer needs, pain points, or desires discovered through continuous weekly customer interviews; 3) Solutions (Leaves): Multiple distinct product feature ideas that could address each specific opportunity; 4) Assumption Tests (Sub-leaves): Small experiments, prototypes, or spikes designed to de-risk key assumptions before committing engineering resources to build the complete solution."),

        (40, "How do you decide between a Freemium business model and a Free Trial model?", "Medium",
         ["freemium", "free trial", "business model", "monetization", "marginal cost", "conversion rate", "PLG"],
         "Freemium works when marginal server costs are near zero, viral network effects exist, and features can be naturally gated. Free Trial works for high-touch, complex products.",
         "The choice depends on product mechanics and marginal costs: 1) Freemium provides perpetual access to a stripped-down feature set. It succeeds when: marginal compute/storage cost per free user is near zero, natural network effects encourage users to invite colleagues, and clear feature gates or usage limits incentivize upgrading (e.g., Slack's 90-day message history, Spotify ads). However, free-to-paid conversion rates are typically low (2%-5%); 2) Free Trial (14-30 days) provides full access to premium features for a limited time. It succeeds when the product has high operational/server costs, requires significant onboarding, or solves high-value enterprise problems (conversion rates are often 15%-25%)."),
    ]

    topics_41_to_100 = [
        (41, "Explain the MoSCoW prioritization technique and how to avoid the 'Everything is Must-Have' trap.", 'Easy', ['MoSCoW', 'must have', 'should have', 'could have', 'wont have', 'prioritization', 'scope management'], "Define categories (Must, Should, Could, Won't have this time). Enforce a rule that Must-Haves cannot exceed 60% of total team capacity.", "MoSCoW categorizes requirements into four tiers: Must-Have (non-negotiable launch blockers without which the product cannot legally or functionally operate), Should-Have (important capabilities that add significant value but have acceptable temporary workarounds), Could-Have (nice-to-have delighters if time permits), and Won't-Have (explicitly agreed out of scope for this release). To prevent the common trap where stakeholders classify every pet feature as 'Must-Have', I enforce strict capacity allocation caps: Must-Haves may not exceed 60% of total sprint capacity, leaving 40% reserved for Should-Haves, Could-Haves, and unforeseen execution buffers."),
        (42, 'How do you calculate Cost of Delay and Weighted Shortest Job First (WSJF)?', 'Hard', ['cost of delay', 'WSJF', 'SAFe', 'user business value', 'time criticality', 'risk reduction', 'job size'], 'WSJF = Cost of Delay / Job Size. Cost of Delay = User-Business Value + Time Criticality + Risk Reduction / Opportunity Enablement.', 'Cost of Delay quantifies the financial or strategic impact of not having a feature available today. Weighted Shortest Job First (WSJF) prioritizes backlog items to maximize economic throughput by dividing Cost of Delay by Job Duration / Size: WSJF = Cost of Delay / Job Size. Cost of Delay is calculated as the sum of three components scored on a relative Fibonacci scale: 1) User-Business Value (monetary revenue or customer value); 2) Time Criticality (urgency, seasonal deadlines, contractual commitments); and 3) Risk Reduction / Opportunity Enablement (unblocking future strategic capabilities). Prioritizing high-WSJF features delivers the highest economic return in the shortest time.'),
        (43, 'What is the DAU/MAU Stickiness Ratio and what benchmarks indicate healthy product engagement?', 'Medium', ['DAU MAU', 'stickiness', 'daily active users', 'monthly active users', 'engagement', 'SaaS benchmark', 'retention'], 'DAU/MAU measures how many monthly users return daily. Benchmarks: 10-20% for enterprise B2B SaaS, 50%+ for world-class consumer social.', 'The DAU/MAU ratio (Daily Active Users divided by Monthly Active Users) measures user engagement frequency and habit-forming stickiness—essentially, the proportion of monthly users who return to the product on any given average day. Healthy benchmarks vary significantly by product category: enterprise B2B SaaS tools (e.g., HR portals or invoicing software) typically consider 10% to 20% healthy because users only need them periodically. Daily operational tools (like Slack or Notion) target 30% to 40%. World-class consumer social apps (WhatsApp, Instagram) exceed 50%, reflecting strong daily habitual retention.'),
        (44, 'Explain Attribution Modeling: First-Touch vs Last-Touch vs Multi-Touch attribution.', 'Medium', ['attribution modeling', 'first touch', 'last touch', 'multi touch', 'customer journey', 'marketing spend', 'CAC'], 'Compare First-Touch (credits initial discovery), Last-Touch (credits closing channel), and Multi-Touch (linear, time-decay, W-shaped crediting all touchpoints).', 'Attribution modeling assigns credit across marketing touchpoints along a customer conversion journey: 1) First-Touch Attribution awards 100% of credit to the initial channel that introduced the customer (e.g., top-of-funnel blog post or brand ad). It highlights brand awareness drivers but ignores nurturing channels; 2) Last-Touch Attribution awards 100% of credit to the final touchpoint before purchase (e.g., a branded search ad or demo form). It emphasizes closing channels but undervalues awareness; 3) Multi-Touch Attribution (Linear, Time-Decay, or W-shaped) distributes fractional credit across all touchpoints, providing an accurate, holistic picture of the customer journey.'),
        (45, 'How do you structure Go-to-Market (GTM) launch tiers (Tier 1 vs Tier 2 vs Tier 3)?', 'Medium', ['GTM', 'go to market', 'launch tiers', 'marketing', 'sales enablement', 'press release', 'tier 1 launch'], 'Tier 1: Major game-changer (PR, keynote, full sales enablement). Tier 2: Meaningful feature (blog, in-app banner, email). Tier 3: Minor enhancement (changelog).', 'To prevent cross-functional launch fatigue, I categorize product releases into three GTM tiers: 1) Tier 1 (Strategic Milestone): Company-defining capability opening new markets or enterprise segments. Requires full marketing orchestration: executive press release, keynote webinar, customer case studies, dedicated sales battlecards and demo certification, in-app feature tours, and global PR; 2) Tier 2 (Significant Feature): Meaningful enhancement for existing users. Supported by product blog post, targeted customer email newsletters, in-app announcement modals, and sales updates; 3) Tier 3 (Continuous Polish): Minor UI improvements, performance boosts, or small bug fixes. Documented via public release changelogs and documentation updates.'),
        (46, 'What is Net Revenue Retention (NRR) and why is it considered the holy grail metric for SaaS?', 'Hard', ['NRR', 'net revenue retention', 'GRR', 'expansion revenue', 'churn', 'SaaS health', 'compound growth'], 'Formula: (Starting ARR + Expansion - Contraction - Churn) / Starting ARR. NRR > 100% means the business grows even without acquiring new customers.', 'Net Revenue Retention (NRR) measures the percentage of recurring revenue retained from existing customers over a specific period (typically one year), accounting for customer expansions (upsells, seat additions), contractions (downgrades), and cancellations (churn). NRR = (Starting ARR + Expansion - Contraction - Churn) / Starting ARR. It is considered the gold standard metric by venture investors and executives because an NRR > 100% (with elite benchmarks at 120%-130%+, like Snowflake or Datadog) demonstrates that customer accounts compound in value organically over time, insulating the company from marketing downturns.'),
        (47, 'How do you set effective OKRs (Objectives and Key Results) that focus on outcomes rather than outputs?', 'Medium', ['OKRs', 'objectives', 'key results', 'outcomes vs outputs', 'goal setting', 'alignment', 'metrics'], 'Objectives are inspirational qualitative goals; Key Results are measurable, outcome-driven metrics (never a checklist of shipped features).', "Effective OKRs align teams around customer and business outcomes rather than feature output checklists: 1) Objective (O): An ambitious, qualitative, memorable statement of intent defining where we want to go (e.g., 'Make team onboarding effortless and viral'); 2) Key Results (KRs): 3 to 5 measurable, quantitative milestones that prove the objective was met. Output-based KRs ('Ship 3 onboarding screens') are bad because you can ship screens that fail to move the business. Outcome-based KRs ('Increase Day-14 team activation rate from 22% to 35%', 'Reduce time-to-first-collaboration from 48h to 2h') measure true business impact."),
        (48, 'How do you write effective User Stories with Given-When-Then Acceptance Criteria?', 'Easy', ['user story', 'acceptance criteria', 'given when then', 'BDD', 'agile', 'behavior driven development', 'product management'], 'User story format: As a [persona], I want [action], so that [benefit]. Acceptance criteria: Given [precondition], When [action], Then [expected outcome].', "A well-structured user story captures the persona, the need, and the underlying motivation: 'As a [specific user persona], I want [to perform an action], so that [I can achieve a measurable benefit].' To eliminate ambiguity for engineering and QA, I write Acceptance Criteria using the Gherkin Given-When-Then format (Behavior-Driven Development): 'Given [an initial state or context, e.g., an authenticated user with an expired credit card], When [the user clicks the checkout button], Then [display a friendly payment update modal with auto-retry, and log an analytics event]'. This creates clear test cases and defines explicit boundary conditions."),
        (49, 'What is the difference between the Definition of Ready (DoR) and the Definition of Done (DoD)?', 'Easy', ['definition of ready', 'definition of done', 'DoR', 'DoD', 'agile', 'sprint planning', 'quality assurance'], 'DoR ensures a ticket is clear and ready to be picked up by engineering; DoD ensures completed code meets production release standards.', 'Both definitions act as quality gates in the agile lifecycle: 1) Definition of Ready (DoR): Criteria a user story must satisfy before an engineering squad accepts it into an active sprint. It ensures tickets have a clear problem statement, validated design mocks, finalized copy, Given-When-Then acceptance criteria, identified backend dependencies, and estimated story points, preventing developer blockers during the sprint; 2) Definition of Done (DoD): Criteria a completed task must satisfy before being considered releasable: code passes peer review, unit and integration tests exceed coverage thresholds, documentation is updated, and security scans pass.'),
        (50, 'How do you perform a 5 Whys Root Cause Analysis when a key product metric suddenly drops?', 'Medium', ['5 whys', 'root cause analysis', 'incident management', 'metric drop', 'debugging', 'investigation'], 'Walk through an iterative interrogative drill-down from the superficial symptom down to the systemic process or technical failure.', 'When an essential metric drops unexpectedly (e.g., daily checkout completion drops by 20%), the 5 Whys systematically uncovers the systemic root cause: 1) Why did checkouts drop? Because mobile users encountered error screens on payment; 2) Why did they encounter error screens? Because the payment gateway rejected Apple Pay tokens; 3) Why were tokens rejected? Because our recent frontend update changed the merchant payload schema; 4) Why did the payload change without gateway verification? Because the payment team did not run end-to-end integration tests on staging; 5) Why were integration tests skipped? Because the CI/CD pipeline lacked automated end-to-end payment gateway mocks. The corrective action is adding mandatory automated gateway contract tests.'),
        (51, 'How do you conduct a Cannibalization Analysis when launching a new tier or product variant?', 'Medium', ['cannibalization', 'product tier', 'revenue impact', 'pricing', 'market expansion', 'net new revenue'], 'Evaluate whether the new product expands total TAM or merely shifts existing paying customers into a cheaper/lower-margin tier.', 'Cannibalization occurs when a new product offering or pricing tier absorbs existing sales from your current products rather than generating incremental net-new customers. To evaluate cannibalization: 1) Segment Analysis: Model customer migration scenarios—what percentage of current Pro subscribers ($50/mo) will downgrade to a new Starter tier ($20/mo)? 2) Net-New Expansion vs Substitution: Compare projected cannibalized revenue against incremental net-new customer acquisition from previously unserved price-sensitive cohorts; 3) Feature Fencing: Ensure the lower tier omits advanced features essential to high-value enterprise users (e.g., SAML SSO, audit logs, unlimited seats) so premium accounts have zero incentive to downgrade.'),
        (52, 'How do you structure a Moderated Usability Testing protocol with 5 target users?', 'Medium', ['usability testing', 'think aloud', 'user research', 'moderated testing', 'friction', 'Nielsen Norman', 'prototype'], 'Use Steve Krug and Nielsen Norman principles: give users real tasks without guiding them, encourage think-aloud protocol, and observe where they get stuck.', "Nielsen Norman research proves that testing with just 5 users uncovers approximately 85% of usability flaws. My testing protocol: 1) Welcome & Disclaimers: Remind the participant 'We are testing the prototype, not you; you cannot make a mistake, and candid feedback is most valuable'; 2) Context Gathering: 5 minutes understanding their daily workflow; 3) Scenario-Based Tasks: Provide realistic tasks without giving hints or instructions (e.g., 'Imagine you need to onboard 3 colleagues to this workspace. Show me how you would accomplish that'); 4) Think-Aloud Protocol: Prompt users to verbalize their thoughts; 5) Observation: Note where users hesitate, mis-click, or express confusion."),
        (53, 'What are the distinct phases of a Beta Testing Program (Alpha vs Closed Beta vs Open Beta vs GA)?', 'Easy', ['beta testing', 'alpha', 'closed beta', 'open beta', 'general availability', 'GA', 'feedback loops'], 'Alpha (internal employees) -> Closed Beta (handpicked NDA customers) -> Open Beta (public opt-in) -> General Availability (100% rollout).', "A disciplined release progression mitigates operational risk: 1) Alpha: Internal testing by employees and developers to identify gross functional bugs and validate core workflows; 2) Closed Beta: Limited rollout to a handpicked cohort of 10-50 highly engaged, design-partner customers under NDA. Focus is on qualitative feedback, workflow validation, and edge-case discovery; 3) Open Beta: Public opt-in release available to all users with a 'Beta' badge. Focus shifts to quantitative stress-testing: backend infrastructure scaling, concurrency limits, and self-serve onboarding telemetry; 4) General Availability (GA): Full commercial launch accompanied by sales enablement, SLAs, marketing campaigns, and billing activation."),
        (54, 'How do you build Sales Battlecards and collaborate with Enterprise Sales teams?', 'Medium', ['sales enablement', 'battlecard', 'competitive intelligence', 'enterprise sales', 'objection handling', 'FUD'], 'Structure battlecards: Competitor Overview -> Quick Kill Points -> Landmines to Lay -> Pricing Comparison -> Common Objection Handling.', "Sales Battlecards equip account executives with concise, actionable intelligence to win competitive deals. A great battlecard includes: 1) Quick Competitor Snapshot: Target customer, pricing model, and high-level positioning; 2) Quick Kill Points: 2-3 decisive advantages where our product demonstrably outperforms the rival; 3) Landmines to Lay: Questions for the sales rep to prompt the prospect with that highlight the competitor's known weaknesses (e.g., 'Ask them how their system handles cross-region disaster recovery'); 4) Competitor Strengths & How to Pivot: Candidly acknowledging where the rival is strong and reframing the conversation; and 5) Real Objection Handling scripts."),
        (55, 'How do you manage cross-cultural and timezone friction when working with Offshore Development squads?', 'Medium', ['offshore teams', 'remote management', 'async communication', 'timezone', 'documentation', 'sprint cadence'], 'Shift toward asynchronous documentation-first culture (PRDs, Loom walkthroughs, Slack), establish overlapping golden hours, and treat offshore engineers as core teammates.', "Managing distributed and offshore engineering squads requires moving from synchronous verbal alignment to structured asynchronous clarity: 1) Asynchronous Documentation-First: Ensure PRDs, user stories, architectural diagrams, and Loom video walkthroughs are finalized before sprint kickoff, eliminating blockers during timezone disconnects; 2) Overlapping Golden Hours: Establish 1-2 hours of daily calendar overlap dedicated to standups, sprint grooming, and unblocking questions; 3) Culture and Inclusion: Avoid treating offshore engineers as an 'order-taking factory'; include them in product discovery context, celebrate their wins, and share customer feedback so they understand the business 'why' behind the code."),
        (56, 'How do you prioritize Internationalization (i18n) and Localization (l10n) expansion?', 'Hard', ['internationalization', 'localization', 'i18n', 'l10n', 'global expansion', 'local payment methods', 'market expansion'], 'Evaluate market demand (organic traffic from region), localize currency and payment methods (Pix, iDEAL), before investing in full language translation.', 'International expansion requires a phased ROI-driven framework: 1) Quantify Inbound Signals: Analyze web traffic and signups by country to identify markets demonstrating strong organic demand despite language barriers; 2) Regulatory & Payment Infrastructure: Frequently, local payment methods (e.g., Pix in Brazil, iDEAL in Netherlands, UPI in India) drive higher conversion lifts than translating text; 3) Internationalization (i18n) Readiness: Ensure backend systems support multi-currency, date/time formatting, right-to-left (RTL) scripts, and UTF-8 encoding; 4) Localization (l10n): Tier translation investments—first localizing marketing landing pages and onboarding flows before translating deep settings menus.'),
        (57, 'How do you design a Product Analytics Event Taxonomy using the Object-Action framework?', 'Medium', ['event taxonomy', 'analytics', 'tracking plan', 'object action', 'Segment', 'Mixpanel', 'Amplitude'], "Use standardized naming conventions: [Object] [Action] (e.g., 'Document Exported', 'Workspace Created') with structured, consistent properties.", "A chaotic event taxonomy results in fragmented analytics and unusable dashboards. I enforce the standardized Object-Action framework: 1) Event Naming Convention: Events are named strictly as `[Entity/Object] [Action in Past Tense]` (e.g., `Project Created`, `Invoice Sent`, `Member Invited`, `Search Executed`); 2) Standard Global Properties: Every event automatically includes ambient properties (user_id, account_id, platform, app_version, timestamp); 3) Specific Contextual Properties: Explicit attributes relevant to the interaction (e.g., `Document Exported` includes format: 'PDF', word_count: 1420, duration_seconds: 4); 4) Single Source of Truth Tracking Plan maintained in a version-controlled schema."),
        (58, 'How do you handle a bespoke feature request from a multi-million-dollar Enterprise client?', 'Hard', ['enterprise customer', 'custom feature', 'bespoke', 'platform roadmap', 'professional services', 'feature request'], 'Never build one-off custom code into core software. Uncover the underlying job-to-be-done and solve it via extensible APIs, webhooks, or platform features.', 'When an enterprise client demands custom bespoke functionality: 1) Uncover the Underlying Business Problem: Schedule an architecture session to understand their exact technical workflow rather than blindly accepting their proposed implementation; 2) Evaluate Platform Alignment: Can this capability be designed as a generalized, extensible platform feature that benefits multiple enterprise customers? If yes, prioritize it on the core roadmap; 3) Extensibility Solutions: If the request is unique to their internal legacy system, empower them to build it using our public REST APIs, Webhooks, or App Marketplace integrations; 4) Partner / Professional Services: Connect them with certified integration partners rather than polluting core product code with one-off logic.'),
        (59, 'What is Dual-Track Agile, and how do Discovery and Delivery tracks run concurrently?', 'Medium', ['dual-track agile', 'discovery track', 'delivery track', 'continuous discovery', 'Jeff Patton', 'agile'], 'Discovery track rapidly validates customer problems and prototypes; Delivery track engineers production-ready scalable software in parallel.', 'Dual-Track Agile (popularized by Jeff Patton and Marty Cagan) divides product development into two parallel, continuous tracks: 1) Discovery Track: Led by the PM, Product Designer, and Tech Lead. The goal is rapid learning, de-risking value, usability, feasibility, and business viability through prototypes, customer interviews, and quick spikes; 2) Delivery Track: Focused on building production-grade, tested, scalable, and deployable code in sprints. Items validated in the Discovery Track flow smoothly into the Delivery Track backlog, ensuring engineers build only validated, high-conviction features and minimizing wasted code.'),
        (60, 'What are Continuous Discovery Habits and how do you implement them weekly?', 'Easy', ['continuous discovery', 'customer interviews', 'Teresa Torres', 'feedback loops', 'customer empathy', 'weekly habits'], 'Commit to talking to at least 2-3 real customers every single week to maintain an unbroken stream of qualitative insights.', "Continuous Discovery Habits (Teresa Torres) shifts customer research from an episodic event before major redesigns into a continuous weekly cadence. Implementation: 1) Automate Customer Recruiting: Embed an automated Calendly link in post-cancellation screens, high-usage events, or support follow-ups so that 2-3 customer interviews are scheduled automatically on the PM's calendar every week; 2) Triad Participation: The PM, Lead Designer, and an Engineer attend together, taking turns interviewing and taking notes; 3) Focus on Recent Stories: Ask users about their actual recent workflows; 4) Synthesize Insights immediately into opportunity maps."),
        (61, 'How do Card Sorting and Tree Testing optimize product Information Architecture (IA)?', 'Easy', ['card sorting', 'tree testing', 'information architecture', 'IA', 'navigation', 'menu design', 'usability'], 'Card sorting (generative, users group cards into categories) creates the IA mental model; Tree testing (evaluative, users navigate text trees) validates findability.', 'Information Architecture (IA) structures how content and features are organized and navigated: 1) Card Sorting (Generative): Participants are given a deck of cards representing product features or pages. In Open Card Sorting, users organize items into natural groups and assign their own category labels, revealing user mental models and natural taxonomy; in Closed Card Sorting, users place items into predefined categories, testing categorization logic; 2) Tree Testing (Evaluative): Users are presented with a text-only hierarchical menu tree stripped of visual design and asked to find specific items. Tree testing isolates navigational findability and measures directness and success rates.'),
        (62, 'How do you design high-converting In-App Upgrade Prompts without frustrating free users?', 'Medium', ['in-app upgrade', 'paywall', 'feature gating', 'freemium', 'conversion rate', 'PLG', 'monetization'], 'Contextual placement at the moment of intent: explain the specific unlocked benefit, provide a free trial of the feature, and maintain graceful dismissibility.', "Intrusive, blanket popups degrade user trust. High-converting upgrade prompts follow contextual principles: 1) Trigger at the Moment of Intent: Display prompts when a user actively clicks or attempts to use an advanced capability (e.g., attempting to export in 4K resolution or invite an 11th team member) rather than upon login; 2) Highlight the Specific Value Unlock: Frame copy around the immediate benefit ('Unlock unlimited PDF exports and automated audit trails') rather than generic 'Upgrade to Pro'; 3) Low-Friction Trial: Offer a 1-click 14-day trial of the feature without immediate credit card requirements; 4) Always allow easy dismissal."),
        (63, 'What are Dark Patterns in UI/UX, and where do you draw the line between growth hacking and ethics?', 'Easy', ['dark patterns', 'growth hacking', 'ethics', 'roach motel', 'confirmshaming', 'misdirection', 'trust'], 'Dark patterns trick users into unintended actions (Roach Motel, Confirmshaming, Hidden Costs). They yield short-term gains but destroy long-term LTV and brand trust.', "Dark Patterns are manipulative user interfaces designed to deceive users into taking actions they might not otherwise choose: 1) Roach Motel: Easy to subscribe, but cancellation requires phone calls during business hours; 2) Confirmshaming: Guilt-tripping copy on dismiss buttons (e.g., 'No thanks, I hate saving money'); 3) Hidden Continuity: Subscriptions renewing without notice after free trials. While dark patterns can temporarily inflate short-term acquisition or retention vanity metrics, they destroy brand reputation, provoke chargebacks and regulatory fines (FTC enforcement), and devastate long-term customer lifetime value. Ethical growth aligns business value with transparent user agency."),
        (64, "Explain the dynamics of Two-Sided Marketplaces and how to solve the 'Chicken-and-Egg' problem.", 'Hard', ['two-sided marketplace', 'chicken and egg', 'network effects', 'supply and demand', 'Uber', 'Airbnb', 'liquidity'], 'Almost always subsidize and seed SUPPLY first. Create single-player utility for the initial side, then aggregate demand.', 'Two-sided marketplaces (Uber, Airbnb, DoorDash) connect distinct user groups (Supply and Demand), where neither side has incentive to join without the other (the Chicken-and-Egg problem). Strategies to solve it: 1) Subsidize and Seed Supply First: Supply is almost always harder to acquire than demand; seed supply by offering financial guarantees, concierge onboarding, or manually scraping listings (like Airbnb cross-posting to Craigslist); 2) Single-Player Mode: Give the supply side a standalone software utility that provides value even before buyers arrive (e.g., OpenTable providing table management software to restaurants first); 3) Constrain Geography: Launch in a tight geographic cluster (e.g., Uber launching in SF only) to achieve critical liquidity before expanding.'),
        (65, 'What is the difference between Pipeline and Platform business models?', 'Medium', ['platform', 'pipeline', 'ecosystem', 'network effects', 'value creation', 'APIs', 'business model'], 'Pipeline models create linear value (step-by-step supply chain); Platform models facilitate exchanges between external producers and consumers.', "In 'Platform Revolution' (Parker, Van Alstyne): 1) Pipeline Businesses operate a linear value chain: the company purchases raw inputs, manufactures a product, and sells it linearly down the distribution pipe to consumers (e.g., traditional retailers, automotive manufacturers, standard software vendors); 2) Platform Businesses provide plug-and-play digital infrastructure that enables external producers and external consumers to connect, interact, and exchange value directly (e.g., iOS App Store, YouTube, Uber). Platforms scale with zero marginal inventory costs, leveraging decentralized network effects and external ecosystem innovation to capture outsized market cap."),
        (66, 'How do you treat an API as a Product, and what metrics define Developer Experience (DX)?', 'Medium', ['API product', 'developer experience', 'DX', 'documentation', 'SDK', 'API-first', 'time to first call'], 'Treat developers as users: evaluate Time to First Hello World (TTFHW), documentation searchability, SDK coverage, and backwards compatibility.', 'When an API is the commercial product (e.g., Stripe, Twilio, SendGrid), developers are your primary user persona: 1) Time-to-First-Hello-World (TTFHW): The minutes required for a developer to sign up, generate an API key, copy a curl/SDK snippet, and receive an HTTP 200 response with live test data (Stripe benchmark is < 5 minutes); 2) Interactive Documentation: Copyable code samples in all major languages with pre-populated keys; 3) Idiomatic Official SDKs (Python, Node, Go, Java); 4) Comprehensive Sandbox/Mock environments; 5) Clear, human-readable error payloads with direct links to documentation; and 6) Strict semantic versioning and non-breaking contract guarantees.'),
        (67, 'What is Time-to-First-Hello-World (TTFHW) and how do you optimize it?', 'Easy', ['TTFHW', 'developer experience', 'onboarding', 'quickstart', 'API key', 'frictionless', 'developer onboarding'], 'Measure the exact seconds from landing on docs to successful API call. Eliminate sign-up friction, provide sandbox keys, and pre-built code sandboxes.', 'Time-to-First-Hello-World (TTFHW) is the premier developer activation metric, measuring the elapsed time from when a developer discovers your API documentation to when they successfully execute their first working API call. To optimize TTFHW: 1) Zero-Auth Interactive Sandboxes: Embed runnable code editors directly within documentation pages allowing users to test endpoints before registering; 2) 1-Click Key Provisioning: Generate pre-configured test API keys immediately upon signup without requiring email confirmation or credit cards; 3) Copy-Paste Quickstarts with pre-filled test keys; 4) Pre-built Postman Collections and official CLI tools.'),
        (68, 'What are the trade-offs of Usage-Based Pricing vs Per-Seat Pricing?', 'Medium', ['usage-based pricing', 'per-seat pricing', 'pricing model', 'revenue predictability', 'growth', 'Snowflake'], 'Per-seat offers revenue predictability but disincentivizes team adoption; Usage-based aligns directly with customer value but introduces revenue volatility.', '1) Per-Seat Pricing (Per-User) charges a fixed monthly fee per active employee seat (e.g., Salesforce, Slack). Pros: Predictable recurring revenue (ARR) and straightforward sales forecasting. Cons: Creates friction where companies actively restrict seat access to save money, hindering viral bottom-up adoption; 2) Usage-Based Pricing (Consumption) charges based on volume metrics consumed (e.g., compute hours, gigabytes stored, API credits, like Snowflake and AWS). Pros: Zero upfront adoption barrier, perfect alignment with customer value (pay as you grow), and uncapped revenue expansion. Cons: Revenue volatility, seasonal fluctuations, and customer anxiety over unpredictable monthly billing bills.'),
        (69, 'How do you construct a Customer Health Score to predict and preempt Churn?', 'Medium', ['customer health score', 'churn prediction', 'customer success', 'telemetry', 'leading indicator', 'retention'], 'Combine behavioral telemetry (DAU, core feature usage), business indicators (contract age, license utilization), and relationship signals (NPS, support tickets).', "A Customer Health Score provides an aggregated leading indicator (typically scored 0-100 into Green, Yellow, Red bands) predicting customer renewal and churn risk. It synthesizes three weighted categories: 1) Product Telemetry (50%): Frequency of logins, seat license utilization (% of purchased seats active), and execution of key 'Aha' workflows within the past 14 days; 2) Service & Support Signals (25%): Volume and severity of open customer support tickets, unresolved bug escalation frequency, and CSAT survey ratings; 3) Commercial Relationship (25%): Time to contract renewal, executive sponsor turnover, and invoice payment timeliness. Red flags trigger automated alerts for Customer Success Managers to intervene proactively."),
        (70, 'How do you establish Product Vision vs Strategy vs Roadmap vs Backlog?', 'Easy', ['product vision', 'product strategy', 'roadmap', 'backlog', 'alignment', 'hierarchy', 'execution'], 'Vision is the North Star (Where); Strategy is the path (How); Roadmap is the strategic milestones (What & When); Backlog is the sprint tasks (Details).', "These artifacts form a cascading strategic hierarchy: 1) Product Vision: The ultimate inspirational North Star describing the future state of the world your product aims to create over a 5-10 year horizon (the 'Where' and 'Why'); 2) Product Strategy: The cohesive set of choices, target customer segments, positioning moats, and business models that dictate how the company will win against competitors over 1-3 years (the 'How'); 3) Product Roadmap: Strategic thematic milestones and outcome-driven problems the team commits to tackling across sequential quarters (the 'What and When'); 4) Backlog: The tactical, granular list of user stories, bug fixes, and engineering tasks executed in upcoming sprints (the 'Details')."),
        (71, 'What is the Build-Measure-Learn feedback loop and how do you shorten its cycle time?', 'Easy', ['build measure learn', 'lean startup', 'cycle time', 'experimentation', 'validation', 'Eric Ries', 'iteration'], 'Start with Learn (identify hypotheses), determine what to Measure, then Build the smallest artifact (prototype/smoke test). Speed of loop = speed of innovation.', 'The Build-Measure-Learn feedback loop (Eric Ries) is the core engine of the Lean Startup methodology. While named Build-Measure-Learn, effective product managers plan the loop in reverse: 1) Learn: Clearly state the critical hypothesis or unanswered customer question; 2) Measure: Determine the exact metric and quantitative threshold that will validate or invalidate the hypothesis; 3) Build: Create the smallest possible artifact—a prototype, clickable mockup, landing page smoke test, or lightweight MVP—required to capture that measurement. Shortening cycle time (from months to days) accelerates organizational learning velocity and prevents building unwanted software.'),
        (72, 'How do you calculate the Van Westendorp Price Sensitivity Meter?', 'Hard', ['van Westendorp', 'price sensitivity', 'pricing research', 'willingness to pay', 'optimal price point', 'survey'], 'Survey 4 questions: At what price is it: 1) Too cheap? 2) A bargain? 3) Expensive? 4) Too expensive? Plot cumulative curves to find the Optimal Price Point.', 'The Van Westendorp Price Sensitivity Meter is a quantitative survey technique used to determine market price elasticity and willingness to pay. Respondents are shown a product description and asked four specific price questions: 1) At what price is it so cheap you would question its quality? (Too Cheap); 2) At what price is it a bargain—a great buy for the money? (Cheap); 3) At what price is it starting to get expensive, but you would still consider it? (Expensive); 4) At what price is it so expensive you would never consider it? (Too Expensive). Plotting the cumulative percentages of responses generates intersecting curves that identify the Range of Acceptable Pricing and the Optimal Price Point (OPP).'),
        (73, 'Why should Accessibility (WCAG 2.1 AA) be prioritized as a core product requirement?', 'Easy', ['accessibility', 'WCAG', 'a11y', 'inclusive design', 'screen reader', 'compliance', 'legal risk'], 'Explain that accessibility expands addressable market, improves baseline SEO and UX for all users, and protects against catastrophic legal ADA lawsuits.', 'Accessibility (a11y) is not merely a legal compliance checkbox; it is a foundational product quality requirement: 1) Market Expansion: Approximately 15% of the global population lives with disabilities; inaccessible software artificially cuts off 15% of potential TAM; 2) Better Baseline UX: Principles of accessibility (high contrast text, intuitive keyboard navigation, clear heading hierarchy, semantic HTML) improve usability for all users, including those on mobile screens under bright sunlight or with temporary injuries; 3) Legal Compliance & Enterprise Readiness: Enterprise procurement contracts strictly mandate WCAG 2.1 AA and VPAT compliance, and failure to comply exposes companies to costly ADA litigation.'),
        (74, 'How do you design a Product Experimentation culture that embraces failed tests?', 'Medium', ['experimentation culture', 'failed tests', 'hypotheses', 'learning velocity', 'A/B testing', 'psychological safety'], 'Celebrate invalidating incorrect hypotheses early before building production code. A test only fails if no learning is extracted.', "In high-performing experimentation organizations (like Booking.com or Netflix), a 'negative' A/B test is not considered a failure—it is a successful prevention of deploying code that would have harmed the business. To foster this culture: 1) Focus on Hypotheses: Frame every feature as a testable assumption ('We believe that doing X for persona Y will achieve outcome Z'); 2) Measure Velocity of Validated Learnings rather than raw win rates (since 70-80% of well-designed experiments fail to move metrics); 3) Publicly Share and Celebrate Learnings from failed tests in company town halls; and 4) Establish automated testing guardrails so anyone can test safely."),
        (75, 'What are Peeking and Novelty Bias in A/B testing, and how do you avoid them?', 'Hard', ['peeking problem', 'novelty effect', 'A/B testing', 'statistical significance', 'p-hacking', 'sample size'], 'Peeking: stopping a test the moment p < 0.05 inflates false positives by 3-5x. Novelty: users click new UI changes temporarily before reverting to baseline.', '1) The Peeking Problem occurs when PMs continuously monitor real-time A/B test dashboards and declare victory the moment p-value dips below 0.05. Because statistical metrics oscillate naturally due to random noise, peeking and stopping early inflates false positive error rates from 5% to over 30%. Mitigate by pre-determining sample size upfront and holding until completion, or using sequential testing algorithms (like Always Valid p-values); 2) Novelty Effect occurs when existing users interact with a new UI element simply because it is novel and unfamiliar, creating an artificial initial lift that fades after 2-3 weeks. Mitigate by running tests for at least 2 full business cycles (14-28 days) and segmenting new vs existing users.'),
        (76, 'How do you manage cross-squad dependencies when launching a multi-team initiative?', 'Medium', ['dependencies', 'cross-squad', 'program management', 'API contracts', 'critical path', 'alignment', 'blockers'], 'Establish agreed API contract interfaces upfront, visualize the Critical Path, and hold joint weekly dependency syncs.', 'Managing dependencies across autonomous squads requires early architectural decoupling: 1) Contract-First Development: Engineering teams define and mock API schemas and contracts upfront, allowing the dependent squad to build against mocks without waiting for backend implementation; 2) Map the Critical Path: Identify the strict chronological sequence of dependent tasks, identifying bottlenecks early; 3) Joint Dependency Sync: PMs meet weekly for a 15-minute operational sync specifically to review shared roadmap milestones and unblock deliverables; 4) Executive Escalation: If a supporting squad deprioritizes a blocking dependency, escalate to leadership with business trade-offs.'),
        (77, 'What is the Lean Canvas and how does it deconstruct a business model on one page?', 'Easy', ['lean canvas', 'Ash Maurya', 'business model', 'value proposition', 'unfair advantage', 'early adopters'], "Explain Ash Maurya's 9 boxes: Problem, Customer Segments, Unique Value Proposition, Solution, Channels, Revenue, Cost, Key Metrics, Unfair Advantage.", "The Lean Canvas (Ash Maurya) adapts Alex Osterwalder's Business Model Canvas into an actionable, 1-page business plan for fast validation. Its 9 components: 1) Problem (top 3 pain points); 2) Customer Segments (target users and early adopters); 3) Unique Value Proposition (single clear compelling message stating why you are different and worth paying attention to); 4) Solution (top 3 features); 5) Channels (pathways to customers); 6) Revenue Streams; 7) Cost Structure; 8) Key Metrics (core activities to track); and 9) Unfair Advantage (moats that cannot be easily copied or bought). It serves as an evolving living document updated after customer discovery cycles."),
        (78, 'How do you design a Role-Based Access Control (RBAC) permission system for an enterprise product?', 'Medium', ['RBAC', 'permissions', 'enterprise', 'roles', 'admin', 'least privilege', 'governance'], 'Separate Roles (Admin, Editor, Viewer) from granular Permissions (can_delete_project, can_invite_member) to maintain security and enterprise scalability.', 'Enterprise procurement mandates granular security controls: 1) Separate Roles from Permissions: Never hardcode permissions to role names. Define granular permissions (e.g., `invoice:read`, `invoice:create`, `member:invite`), and map these permissions into flexible Roles (e.g., Owner, Billing Admin, Editor, Viewer); 2) Principle of Least Privilege: Default new users to read-only Viewer access; 3) Custom Roles for Enterprise: Allow enterprise tier customers to create custom roles mapped to their internal org chart; 4) Audit Logs: Log every permission change, privilege escalation, and access mutation for SOC2 and ISO compliance.'),
        (79, 'How do you responsibly monetize a previously 100% free tool without community backlash?', 'Hard', ['monetization', 'free to paid', 'grandfathering', 'community backlash', 'pricing', 'feature gating'], 'Grandfather existing free users on their active workflows. Monetize on new enterprise-grade capabilities (SSO, unlimited history, team collaboration) rather than stripping existing free features.', 'Monetizing a beloved free product is fraught with community backlash. Best practices: 1) Avoid Clawing Back Existing Free Utility: Stripping away features users relied on for free is seen as a betrayal. Instead, keep core individual workflows free and gate new, advanced capabilities (e.g., advanced analytics, team collaboration, centralized billing, SLA support); 2) Grandfather Legacy Users: Allow existing early adopters to retain their free status or offer deeply discounted lifetime pricing; 3) Transparent Communication: Be honest about business sustainability and server infrastructure costs; 4) Give ample advance notice (60-90 days) before billing gates activate.'),
        (80, 'How do you design an ethical, low-churn Cancellation Flow?', 'Medium', ['cancellation flow', 'churn reduction', 'offboarding', 'retention', 'pause subscription', 'feedback loop', 'exit survey'], 'Make cancellation 1-click self-serve (no dark patterns). Offer flexible alternatives (pause subscription, downgrade tier), and capture structured exit reasons.', "An offboarding flow should be transparent and respectful while actively attempting retention: 1) Self-Serve Simplicity: Allow cancellation in 1-2 clicks directly within settings, complying with legal regulations (FTC Click-to-Cancel); 2) Retention Offers & Pauses: Offer tailored alternatives based on customer circumstances—e.g., 'Take a break: Pause subscription for 1-3 months' or 'Downgrade to free tier'; 3) Exit Reason Categorization: Present a single-question survey ('Why are you cancelling? Expensive / Bugs / Missing feature / Switched to competitor'); 4) Data Export & Preservation: Reassure the user that their data remains safe and exportable, leaving the door open for future re-activation."),
        (81, 'How do you navigate customer pushback and anger following a major UI Redesign?', 'Medium', ['UI redesign', 'customer pushback', 'change aversion', 'opt-in', 'user feedback', 'adoption curve'], 'Acknowledge Change Aversion: muscle memory is broken. Provide opt-in toggle periods, contextual transition tooltips, and separate cosmetic gripes from workflow blockers.', "Whenever a familiar UI changes, users experience natural 'Change Aversion' because their cognitive muscle memory is disrupted. To manage this: 1) Phased Opt-In Beta: Allow users to toggle between 'Classic View' and 'New View' for 30-60 days before deprecating the old UI, giving them agency during the transition; 2) Contextual Micro-Tooltips: Highlight where key tools have moved ('Looking for Export? It is now in the top right menu'); 3) Distinguish Muscle Memory Complaints from Real Broken Workflows: Surface analytics tracking task completion speed—initial slowdowns usually recover within 2 weeks, while sustained drops indicate legitimate design flaws that require iteration."),
        (82, 'What are the fundamental differences between B2B and B2C Product Management?', 'Easy', ['B2B vs B2C', 'buyer vs user', 'sales cycle', 'churn impact', 'emotion vs ROI', 'product management'], 'B2B: Buyer is not the user (ROI/compliance focus, long sales cycles, high contract value). B2C: Buyer is the user (emotional resonance, fast funnels, high volume, low CAC).', '1) Buyer vs User: In B2C, the individual using the app is the purchaser; decisions are emotional, impulsive, and rapid. In B2B, the economic buyer (CIO/VP) is rarely the daily end-user; purchase decisions are driven by ROI calculations, security compliance (SOC2), and integrations; 2) Churn and Revenue Impact: Losing 1 consumer subscriber is negligible; losing 1 enterprise customer paying $500k/year devastates company ARR; 3) Product Discovery: B2C relies on large-scale quantitative A/B testing and funnel analytics; B2B relies heavily on deep qualitative customer discovery interviews, sales feedback loops, and customer advisory boards.'),
        (83, 'How do you prioritize product initiatives when revenue is missing company forecasts?', 'Hard', ['revenue dip', 'crisis management', 'prioritization', 'quick wins', 'expansion revenue', 'retention vs acquisition'], 'Focus on high-velocity revenue realization: plug churn leaks, unblock stalled sales deals with targeted features, and expand existing customer NRR.', 'During a revenue downturn, product leadership must shift focus from speculative multi-year bets to immediate, high-leverage revenue drivers: 1) Plug Churn Leaks: Retaining existing revenue is 5x cheaper than acquiring new customers; analyze recent exit surveys to fix top cancellation blockers; 2) Close Stalled Enterprise Deals: Meet with sales leadership to identify high-value pipeline deals blocked by minor compliance or integration gaps and build them; 3) Frictionless Upsell Paths: Optimize self-serve paywalls and usage-limit notifications to drive expansion revenue; 4) Pause speculative R&D experiments that have long multi-quarter payback periods.'),
        (84, 'How do you sequence Qualitative and Quantitative research in a discovery sprint?', 'Easy', ['research sequencing', 'discovery sprint', 'qualitative', 'quantitative', 'mixed methods', 'triangulation'], 'Sequence: Quant (spot anomalies in data) -> Qual (interview users to understand why) -> Quant (survey/experiment to validate scale across population).', "The most effective discovery workflow follows a mixed-methods sandwich: 1) Initial Quantitative Scan: Analyze telemetry, funnels, and event drop-offs to pinpoint WHERE a problem exists (e.g., '40% of users abandon the checkout at step 2'); 2) Qualitative Deep-Dive: Conduct 5-8 customer interviews and usability sessions to discover WHY users abandon (e.g., 'Users are confused by the unfamiliar terminology on the tax field'); 3) Second Quantitative Validation: Launch an in-app micro-survey or A/B experiment to verify whether this pain point is widespread across the broader user population before building an enterprise-grade solution."),
        (85, 'What is an Ideal Customer Profile (ICP) and how does Product ensure alignment with Sales and Marketing?', 'Medium', ['ICP', 'ideal customer profile', 'sales alignment', 'TAM', 'product-market fit', 'lead qualification'], 'An ICP defines the firmographic, technographic, and behavioral traits of accounts that derive maximum value from your product and retain longest.', "An Ideal Customer Profile (ICP) defines the specific attributes of companies that get the highest value from your product, close fastest in sales cycles, and demonstrate the lowest churn. Attributes include: Firmographics (company size, revenue, industry vertical), Technographics (software stack they use, e.g., 'Must use Salesforce and Snowflake'), and Behavioral triggers (e.g., 'Hiring aggressively in DevOps'). Product managers must align with Sales and Marketing on the ICP: if marketing generates leads outside the ICP, sales closes poor-fit customers who subsequently churn, distorting product roadmap feedback. Tight ICP alignment ensures engineering builds features for customers who stick."),
        (86, 'How can Public Changelogs and Release Notes serve as powerful Retention and Marketing tools?', 'Easy', ['changelog', 'release notes', 'product marketing', 'customer retention', 'transparency', 'momentum'], 'Changelogs demonstrate engineering velocity, re-engage dormant users, build trust, and showcase continuous value delivery.', 'Often treated as an engineering chore, a well-crafted public Changelog (like Linear or Stripe) is a high-leverage marketing and retention vehicle: 1) Demonstrates Rapid Velocity: Consistent weekly or bi-weekly release notes prove to existing customers and prospective buyers that the platform is actively evolving and well-supported; 2) Re-engages Dormant Users: Emailing monthly changelog roundups brings lapsed users back into the app to try newly shipped capabilities; 3) Reduces Support Inquiries: Transparently detailing fixes and improvements prevents redundant support tickets; and 4) Celebrates team craftsmanship.'),
        (87, 'How do you evaluate whether to Acquire an external startup versus building the capability in-house (M&A vs Build)?', 'Hard', ['M&A', 'mergers and acquisitions', 'build vs buy', 'talent acquisition', 'technology integration', 'due diligence'], 'Evaluate Time-to-Market, Team Talent (Acqui-hire), IP defensibility, and the severe friction of technical architecture integration.', 'When evaluating acquiring an external startup versus building internally: 1) Time-to-Market vs Integration Cost: Acquiring buys immediate market share, customer contracts, and working technology, but integrating legacy codebases, distinct database architectures, and conflicting tech stacks frequently takes longer than building from scratch; 2) Talent & Cultural Fit (Acqui-hire): Will the founders and key engineers stay past their earnout period, and do they align with our engineering culture? 3) Strategic Synergy: Does the acquisition open immediate cross-sell opportunities into our existing enterprise customer base? 4) Legal & IP Due Diligence.'),
        (88, 'What is Product Operations (ProdOps) and when should a growing organization hire its first ProdOps manager?', 'Medium', ['product operations', 'ProdOps', 'scaling product', 'cross-functional', 'tooling', 'data democratization'], 'ProdOps standardizes product tooling, democratizes customer data/feedback, streamlines launch readiness, and scales PM best practices.', 'Product Operations (ProdOps) serves a role analogous to DevOps for engineering or RevOps for sales: it scales product management practices across a growing organization. Key responsibilities include: 1) Tooling & Process Standardization: Managing tools (Jira, Figma, Amplitude, LaunchDarkly) and templates (PRDs, retrospectives); 2) Data & Feedback Democratization: Aggregating user research, NPS surveys, and support tickets into centralized dashboards for all PMs; 3) Launch Readiness: Coordinating GTM training with Sales and Customer Success. Companies should hire their first ProdOps manager when the product organization scales beyond 20-30 PMs across multiple product squads.'),
        (89, "How do strategic priorities shift when moving a product from '0 to 1' to '1 to 10'?", 'Medium', ['0 to 1', '1 to 10', 'scaling product', 'product lifecycle', 'optimization', 'technical debt', 'governance'], '0-to-1 is about finding PMF (scrappy, rapid iteration, manual processes). 1-to-10 is about scale, reliability, distribution, and process optimization.', 'The product management mandate shifts fundamentally across growth phases: 1) 0-to-1 (Discovery Phase): Goal is finding Product-Market Fit. Scrappy, rapid experimentation, tolerating technical debt, conducting dozens of user interviews, and pivoting quickly based on qualitative signals; 2) 1-to-10 (Scale Phase): Goal is scaling distribution, operational reliability, and unit economics. Focus shifts to: rebuilding fragile prototypes into resilient microservices, investing in SOC2/GDPR compliance, optimizing conversion funnels, building enterprise permissions (RBAC), and establishing formal cross-functional GTM alignment.'),
        (90, 'What is the difference between an Outcome Roadmap and a Feature Roadmap?', 'Easy', ['roadmap', 'outcome roadmap', 'feature roadmap', 'Now Next Later', 'outputs vs outcomes', 'stakeholder management'], 'Feature roadmaps promise specific UI deliverables on fixed calendar dates (fragile). Outcome roadmaps commit to solving specific customer problems with measurable metrics.', "1) Feature (Gantt-chart) Roadmaps promise specific visual deliverables on fixed calendar dates (e.g., 'Ship Export to Excel by November 15th'). They encourage output over impact, age poorly when estimates slip, and trap teams into shipping obsolete features even if customer needs change; 2) Outcome-Driven Roadmaps (e.g., Now / Next / Later format) organize initiatives around specific customer problems and measurable business metrics (e.g., 'Now: Reduce billing onboarding drop-off by 15%'). This gives the team freedom to iterate on different solutions until the desired outcome is achieved."),
        (91, 'How do you design a Gamification system that drives meaningful retention rather than shallow vanity actions?', 'Medium', ['gamification', 'retention', 'intrinsic motivation', 'extrinsic motivation', 'streaks', 'Duolingo', 'progress bars'], 'Anchor on Intrinsic Motivation (competence, autonomy, progress) rather than shallow badges. Use Streaks, Progress Bars, and Milestones.', 'Shallow gamification (plastering arbitrary badges and leaderboards over boring software) fails because extrinsic rewards lose novelty quickly. Meaningful gamification taps into Intrinsic Motivation (mastery, autonomy, community): 1) Streaks & Loss Aversion: Daily streaks (e.g., Duolingo, GitHub contribution graph) build durable daily habits by leveraging loss aversion; 2) Goal Gradient Progress Bars: Showing profile completion at 80% motivates users to complete the final steps; 3) Unlocking Superpowers: Rewarding frequent users with advanced capabilities or public community recognition.'),
        (92, 'What is Customer Effort Score (CES) and why is it often a better predictor of loyalty than CSAT?', 'Easy', ['customer effort score', 'CES', 'CSAT', 'loyalty', 'frictionless', 'customer service'], "CES measures: 'How easy was it to resolve your issue? 1-7'. Reducing effort drives retention faster than attempting to 'delight' customers.", "Customer Effort Score (CES) asks customers: 'To what extent do you agree with the statement: The company made it easy for me to handle my issue?' (scored 1 to 7). Research from the Corporate Executive Board (The Effortless Experience) revealed that customer loyalty is not built by attempting to 'delight' customers with superficial gestures; it is built by systematically removing friction, frustration, and repeat interactions. Reducing customer effort correlates far more strongly with repeat purchases, reduced churn, and positive word-of-mouth than general Customer Satisfaction (CSAT) scores."),
        (93, 'How do you manage Feature Gating and Entitlements in modern SaaS architectures?', 'Medium', ['feature gating', 'entitlements', 'billing', 'pricing tiers', 'microservices', 'RBAC', 'SaaS architecture'], 'Decouple billing code from application logic: an Entitlements Engine evaluates whether an account has rights to a feature based on plan, addons, and usage.', "Hardcoding billing checks directly into application route handlers (`if user.plan == 'pro'`) creates architectural spaghetti that makes future pricing experiments impossible. A robust system utilizes a dedicated Entitlements Engine: 1) Application code checks abstract capabilities (e.g., `canAccess('bulk_csv_export')`), completely decoupled from billing mechanics; 2) The Entitlements Engine evaluates whether the account has access based on active plan tiers, feature flags, purchased add-on packages, or usage limits; 3) Changes to pricing tiers or promotional access can be configured centrally in the admin console without engineering code deployments."),
        (94, 'What are the common failure modes of OKRs in engineering organizations?', 'Easy', ['OKRs', 'antipatterns', 'goal setting', 'too many goals', 'business as usual', 'sandbagging'], 'Failure modes: Setting too many OKRs (loss of focus), Treating business-as-usual tasks as KRs, Output checklists disguised as KRs, and Lack of weekly check-ins.', "Common OKR failure modes include: 1) Too Many Objectives: Teams set 10 different OKRs, ensuring lack of focus and mediocre execution across all of them (best practice is 2-3 per quarter); 2) BAU (Business As Usual) Disguised as OKRs: Writing standard daily responsibilities ('Respond to customer support tickets') as Key Results rather than ambitious change vectors; 3) Set It and Forget It: Setting OKRs at quarter start and never reviewing them until quarter end; and 4) Weaponizing OKRs for Individual Performance Reviews, which prompts engineers to sandbag goals."),
        (95, 'How do you evaluate and prioritize User Feedback across multiple fragmented channels?', 'Medium', ['feedback synthesis', 'customer feedback', 'tagging', 'repository', 'feature voting', 'customer sentiment'], 'Consolidate feedback into a central repository, tag by customer persona and underlying JTBD problem, and weight by customer ARR.', 'Fragmented feedback across Slack, Zendesk, sales calls, app store reviews, and Gong transcripts must be synthesized systematically: 1) Centralized Ingestion: Channel all customer feedback into a unified repository (e.g., Productboard, Dovetail); 2) Tagging by Problem / Opportunity: Tag entries by underlying customer struggle and feature domain rather than raw solution requests; 3) Weighting by Business Impact: Associate feedback with customer metadata—weighting requests from high-ARR, high-retention ICP accounts higher than free trial churners; 4) Close the Loop: Notify customers when their requested problem has been solved.'),
        (96, 'What is the difference between an API Gateway and an App Marketplace in platform products?', 'Easy', ['API gateway', 'app marketplace', 'platform ecosystem', 'third-party developers', 'integrations', 'network effects'], 'API Gateway is technical plumbing for service routing and auth; App Marketplace is a commercial platform ecosystem connecting 3rd-party developer apps to users.', "1) API Gateway is an infrastructure-level software component that acts as a single reverse proxy entry point for managing, routing, rate-limiting, and authenticating API calls into backend microservices; 2) App Marketplace is a commercial and ecosystem capability that allows third-party developers to build, publish, and monetize integrated applications that extend your platform's core utility for end-users (e.g., Shopify App Store, Slack App Directory, Salesforce AppExchange). Marketplaces transform a software product into a defensible platform with indirect two-sided network effects."),
        (97, 'How do you design a Product Discovery Spike to evaluate technical feasibility?', 'Medium', ['spike', 'technical feasibility', 'discovery', 'risk mitigation', 'timebox', 'proof of concept', 'architecture'], 'Time-box a 2-3 day exploratory engineering spike with clear evaluation criteria to answer a specific technical uncertainty before sprint planning.', "When an innovative feature idea carries high technical uncertainty (e.g., 'Can we process video files on client browsers using WebAssembly?'), committing it to a standard delivery sprint risks blown estimates. An Engineering Discovery Spike resolves this: 1) Time-Boxed: Set a strict, non-negotiable duration (typically 2 to 3 days); 2) Explicit Research Question: Define exactly what unknown must be answered; 3) Disposable Prototype: The goal is not production code, but a throwaway proof-of-concept proving feasibility, performance latency, and API constraints; 4) Clear Deliverable: A technical recommendation document outlining architecture, risks, and realistic sprint story point estimates."),
        (98, 'What is the Product Death Cycle and how do you escape it?', 'Hard', ['product death cycle', 'David Bland', 'feature factory', 'retention', 'user discovery', 'root cause'], 'Cycle: Nobody uses product -> Ask customers what features they want -> Build features -> Nobody uses product. Escape by asking why users struggle with the core product.', "The Product Death Cycle (David Bland) describes a trap where a struggling product continues adding features that fail to improve adoption: 1) Nobody is using the product; 2) The team asks users: 'What features are missing?'; 3) Customers list arbitrary wish-list features; 4) The team builds those features; 5) Nobody uses the new features, and overall engagement remains flat. To escape the cycle: Stop asking customers for solution feature requests. Instead, conduct observational discovery to understand why users are failing to achieve the core 'Aha!' moment in the existing product. Fix onboarding and core value delivery before building secondary features."),
        (99, 'How do you establish clear Product Principles to empower decentralized decision-making?', 'Easy', ['product principles', 'decision making', 'trade-offs', 'team empowerment', 'company values'], "Product principles must help teams resolve real trade-offs (e.g., 'Speed over perfection', 'Simple over powerful'), not generic platitudes.", "Effective Product Principles are not bland platitudes ('We build great software'); they are explicit, opinionated guidelines that help engineers and designers make trade-offs when the PM is not in the room. Great principles explicitly value one positive attribute over another: for example, Stripe's 'Be the developer's friend', or Basecamp's 'Simple over Powerful' (we choose intuitive simplicity even if it means omitting advanced enterprise settings). Clear principles accelerate team velocity, reduce design review bottlenecks, and ensure the product maintains a coherent personality across disparate squads."),
        (100, 'What qualities distinguish an exceptional Senior Product Manager from a Junior PM?', 'Medium', ['senior PM', 'product leadership', 'strategic thinking', 'influence without authority', 'outcomes over outputs', 'executive presence'], 'Junior PMs focus on execution and shipping tickets (Outputs); Senior PMs focus on business outcomes, strategic trade-offs, and influencing without authority.', '1) Execution vs Strategic Context: Junior PMs focus on shipping tickets, managing sprint backlogs, and writing detailed PRDs; Senior PMs focus on business strategy, unit economics, market positioning, and validating whether the feature should be built at all; 2) Output vs Outcome: Juniors celebrate releasing a feature on time; Seniors celebrate moving the North Star metric and reducing customer churn; 3) Influence without Authority: Seniors excel at rallying cross-functional teams around a shared vision through data and empathy, handling difficult stakeholders smoothly, and anticipating risks before they become blockers.'),
    ]

    all_questions = []
    for item in questions_raw + topics_21_to_100 + topics_41_to_100:
        num, text, diff, kws, tips, ans = item
        all_questions.append({
            "id": f"pm_{num}",
            "text": text,
            "difficulty": diff,
            "keywords": kws,
            "tips": tips,
            "model_answer": ans
        })
    return all_questions
